/*
 * A169615  Triangular array: T(n,k)=floor(F(n+k)/F(k)), k=1,2,...,n-2; n>=3,
 *          where F=A000045 (Fibonacci numbers).
 * https://oeis.org/A169615
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is generated by blocks. For each Fibonacci number F_m (m ≥
 *            3) a block begins with F_m. Then it contains floor(F_m / F_k)
 *            for all earlier Fibonacci numbers F_k (k = 2…m‑1, i.e. all
 *            divisors > 1), in increasing order of k. Example blocks: m=3
 *            (F_3=2): 2 m=4 (F_4=3): 3 1 m=5 (F_5=5): 5 2 1 m=6...
 * Range:     u8 n <= 66, u16 n <= 81, u32 n <= 81, u64 n <= 81, u128 n <= 81,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/*  seq_t and idx_t are defined by the build.  */
seq_t a(idx_t n)
{
    /* Fibonacci numbers are stored in a dynamic array.  */
    static seq_t *fib = NULL;        /* previous Fibonacci numbers */
    static idx_t fib_len = 0;        /* number of values currently stored */
    /* Ensure at least the first two Fibonacci numbers (F_1 = F_2 = 1).  */
    if (fib_len < 2) {
        fib = (seq_t *)malloc(2 * sizeof(seq_t));
        fib_len = 2;
        fib[0] = (seq_t)1;
        fib[1] = (seq_t)1;
    }

    idx_t remaining = n;            /* how many more outputs to produce */

    for (idx_t m = 2; ; ++m) {      /* m is the Fibonacci index (F_m) */
        /* Ensure fib[m] exists.  */
        if (m >= fib_len) {
            /* Grow the array: double its size or at least fit up to m.  */
            idx_t new_len = fib_len * 2;
            if (new_len <= m) new_len = m + 1;
            seq_t *tmp = (seq_t *)realloc(fib, new_len * sizeof(seq_t));
            if (!tmp) { /* allocation failure – abort with 0 (undefined) */
                return (seq_t)0;
            }
            fib = tmp;
            /* Compute the missing Fibonacci numbers up to new_len.  */
            for (idx_t i = fib_len; i < new_len; ++i)
                fib[i] = fib[i-1] + fib[i-2];
            fib_len = new_len;
        }

        /* First element of the block: the Fibonacci number itself.  */
        if (remaining == 1) return fib[m];
        remaining--;

        /* Subsequent elements: floor(F_m / F_k) for k = 2 … m-1.  */
        for (idx_t k = 2; k < m; ++k) {
            if (remaining == 1) {
                seq_t val = fib[m] / fib[k];
                return val;
            }
            remaining--;
        }
    }
}
